syntax:
C++ syntax with implementation notes:
```c++
class MyClass {
public:
  MyClass(int val) : value(val) {}
  MyClass(const MyClass& other) { value = other.value; std::cout << "Copy constructor called\n"; }
  int value;
};

MyClass myFunction() {
  MyClass obj(10);
  return obj; // RVO candidate
}

MyClass myFunction2() {
  MyClass obj(10);
  return std::move(obj); // RVO candidate (Move semantics help, but aren't strictly required for RVO/NRVO)
}

MyClass myFunction3(int x) {
  MyClass localObj(x);
  return localObj; // NRVO candidate
}
```

